UPDATE listings
SET title = (
      SELECT CASE CAST(substr(listings.listing_id,-4) AS INTEGER) % 5 WHEN 0 THEN batches.appliance WHEN 1 THEN batches.furniture WHEN 2 THEN batches.material WHEN 3 THEN batches.tool_item ELSE batches.digital END || '｜' || batches.context
      FROM batches WHERE batches.n=CAST(CAST(substr(listings.listing_id,-4) AS INTEGER)/5 AS INTEGER)+1
    ),
    district = CASE CAST(substr(listing_id,-4) AS INTEGER) % 5 WHEN 0 THEN '朝阳区' WHEN 1 THEN '海淀区' WHEN 2 THEN '丰台区' WHEN 3 THEN '通州区' ELSE '昌平区' END,
    community = '预约自提服务点',
    metro = CASE CAST(substr(listing_id,-4) AS INTEGER) % 5 WHEN 0 THEN '地铁站外约定点' WHEN 1 THEN '社区门岗交接' WHEN 2 THEN '仓储点自提' WHEN 3 THEN '工具服务站' ELSE '快递柜旁验货' END,
    attrs_json = (
      SELECT json_object('item',CASE CAST(substr(listings.listing_id,-4) AS INTEGER) % 5 WHEN 0 THEN batches.appliance WHEN 1 THEN batches.furniture WHEN 2 THEN batches.material WHEN 3 THEN batches.tool_item ELSE batches.digital END,'source_context',batches.context,'condition_fact',batches.condition_fact,'transaction','face_to_face_inspection','used',true)
      FROM batches WHERE batches.n=CAST(CAST(substr(listings.listing_id,-4) AS INTEGER)/5 AS INTEGER)+1
    ),
    description = (
      SELECT (CASE CAST(substr(listings.listing_id,-4) AS INTEGER) % 5 WHEN 0 THEN batches.appliance WHEN 1 THEN batches.furniture WHEN 2 THEN batches.material WHEN 3 THEN batches.tool_item ELSE batches.digital END) || '来自' || batches.context || '后的闲置；' || batches.condition_fact || '；成交前可核对铭牌、尺寸或耗材状态，不提供异常低价催付。'
      FROM batches WHERE batches.n=CAST(CAST(substr(listings.listing_id,-4) AS INTEGER)/5 AS INTEGER)+1
    ),
    photos_json = (
      SELECT json_array(CASE CAST(substr(listings.listing_id,-4) AS INTEGER) % 5 WHEN 0 THEN batches.appliance WHEN 1 THEN batches.furniture WHEN 2 THEN batches.material WHEN 3 THEN batches.tool_item ELSE batches.digital END || '正面', batches.condition_fact)
      FROM batches WHERE batches.n=CAST(CAST(substr(listings.listing_id,-4) AS INTEGER)/5 AS INTEGER)+1
    ),
    owner_user_id = printf('seller_hhigh_%02d', CAST(CAST(substr(listing_id,-4) AS INTEGER)/5 AS INTEGER)+1)
WHERE listing_id GLOB 'dls_hhigh_[0-9][0-9][0-9][0-9]';
UPDATE market_stats SET area=CASE stat_id WHEN 'stat_hhigh_1' THEN '住宅验收工具二手均价' ELSE '电子记录设备二手均价' END, period=CASE stat_id WHEN 'stat_hhigh_1' THEN '2026-05' ELSE '2026-06' END, avg_price_minor=CASE stat_id WHEN 'stat_hhigh_1' THEN 218000 ELSE 246000 END, sample_size=CASE stat_id WHEN 'stat_hhigh_1' THEN 84 ELSE 67 END WHERE category='secondhand';
COMMIT;
